function accessPage(){
 const sites=liveSites.map(s=>`<label class="site-check"><input type="checkbox" name="accessSite" value="${esc(s.id)}" checked> ${esc(s.code+" — "+s.nom)}</label>`).join("");
 return pageShell("Gestion des accès","Inviter les membres du personnel et les parents avec des droits limités", "", "", `<div class="notice">Seul l'administrateur général crée les comptes. Chaque compte reçoit automatiquement un numéro AG. La connexion se fait uniquement avec le numéro AG généré et un mot de passe.</div><div class="card" style="margin-top:15px"><h3>Créer un compte / envoyer une invitation</h3><div class="form-grid"><label>Nom<input id="accessNom" required></label><label>Prénoms<input id="accessPrenom" required></label><label>Téléphone (facultatif, non utilisé pour la connexion)<input id="accessPhone" type="tel" placeholder="+229XXXXXXXX"></label><label>Adresse e-mail (facultatif)<input id="accessEmail" type="email"></label><label>Fonction<select id="accessRole" onchange="toggleParentAccess()"><option value="direction">Directeur / Direction</option><option value="censeur">Censeur</option><option value="secretariat">Secrétariat</option><option value="comptable">Comptable</option><option value="enseignant">Enseignant</option><option value="surveillant">Surveillant</option><option value="parent">Parent</option></select></label><label id="parentAccessField" class="full" style="display:none">ID du dossier parent déjà enregistré<input id="accessParentId" type="number" min="1" placeholder="Numéro du dossier parent"></label></div><div id="accessSites" style="margin-top:12px"><b>Établissement(s) autorisé(s)</b><div class="site-checks">${sites}</div></div><button class="btn primary" style="margin-top:16px" onclick="inviteAccess()">Créer le compte</button><p class="muted" id="accessFeedback" aria-live="polite"></p></div><div class="card" style="margin-top:15px"><h3>Règles de sécurité</h3><ul><li>Les rôles d'administrateur ne peuvent pas être créés depuis ce formulaire.</li><li>Un membre du personnel n'accède qu'aux établissements qui lui sont attribués.</li><li>Un compte parent est associé à un dossier parent précis.</li><li>Les bulletins restent réservés à l'administration.</li></ul></div>`);
}
function toggleParentAccess(){const isParent=val("accessRole")==="parent";const f=document.getElementById("parentAccessField"),s=document.getElementById("accessSites");if(f)f.style.display=isParent?"block":"none";if(s)s.style.display=isParent?"none":"block";}
async function inviteAccess(){
 if(!liveMode||!supabaseClient){alert("Connectez-vous avec votre compte administrateur général.");return;}
 const role=val("accessRole");const sites=[...document.querySelectorAll('input[name="accessSite"]:checked')].map(x=>x.value);
 const payload={action:"invite",nom:val("accessNom").trim(),prenom:val("accessPrenom").trim(),email:val("accessEmail").trim(),telephone:val("accessPhone").trim(),role,etablissement_ids:role==="parent"?[]:sites,parent_id:role==="parent"?Number(val("accessParentId")):null};
 const feedback=document.getElementById("accessFeedback");if(!payload.nom||!payload.prenom||false|| (role!=="parent"&&!sites.length)||(role==="parent"&&!payload.parent_id)){feedback.textContent="Complétez le nom, le prénom et les autres champs obligatoires.";return;}
 feedback.textContent="Envoi de l'invitation en cours…";
 const {data,error}=await supabaseClient.functions.invoke("manage-access",{body:payload});
 if(error||data?.error){feedback.textContent="Échec : "+(data?.error||error?.message||"erreur inconnue");return;}
 feedback.innerHTML=(data.message||"Compte créé.")+`<br><b>Numéro de connexion : ${esc(data.login_code||"")}</b><br><b>Mot de passe provisoire : ${esc(data.temporary_password||"")}</b><br><small>Communiquez ces identifiants en privé à la personne. Elle pourra ensuite utiliser son numéro AG et ce mot de passe. Conservez-les avant de fermer cette page.</small>`;
 ["accessNom","accessPrenom","accessEmail","accessPhone","accessParentId"].forEach(id=>{const el=document.getElementById(id);if(el)el.value=""});
}

