function openGradeForm(){if(!db.students.length||!liveSubjects.length)return alert('Ajoutez d’abord les élèves et les matières de cet établissement.');document.getElementById('modalTitle').textContent='Saisir une note';document.getElementById('modalBody').innerHTML=`<div class="form-grid"><label>Élève<select id="gradeStudent">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.class||'')}</option>`).join('')}</select></label><label>Matière<select id="gradeSubject">${liveSubjects.map(m=>`<option value="${m.id}">${esc(m.nom)} · coeff. ${m.coefficient}</option>`).join('')}</select></label><label>Note sur 20<input id="gradeValue" type="number" min="0" max="20" step="0.25" required></label><label>Type d’évaluation<select id="gradeType"><option>Moyenne d’interrogation</option><option>Premier devoir</option><option>Deuxième devoir</option><option>Composition</option><option>Examen</option></select></label><label>Période<select id="gradePeriod"><option>1er trimestre</option><option>2e trimestre</option><option>3e trimestre</option><option>1er semestre</option><option>2e semestre</option></select></label><label class="full">Observation<textarea id="gradeObservation"></textarea></label></div><button class="btn primary" onclick="saveGrade()">Enregistrer la note</button>`;document.getElementById('modal').classList.remove('hidden');}
async function saveGrade(){const note=Number(val('gradeValue'));if(!Number.isFinite(note)||note<0||note>20)return alert('La note doit être comprise entre 0 et 20.');const {data:u}=await supabaseClient.auth.getUser();const student=db.students.find(s=>Number(s.id)===Number(val('gradeStudent'))),mapping=liveClassSubjects.find(x=>Number(x.classe_id)===Number(student?.classId)&&Number(x.matiere_id)===Number(val('gradeSubject'))),subject=liveSubjects.find(x=>Number(x.id)===Number(val('gradeSubject'))),coefficient_applique=Number(mapping?.coefficient||subject?.coefficient||1);const {error}=await supabaseClient.from('notes').insert({etablissement_id:activeSiteId,eleve_id:Number(val('gradeStudent')),matiere_id:Number(val('gradeSubject')),note,type_evaluation:val('gradeType'),periode:val('gradePeriod'),coefficient_applique,observation:val('gradeObservation')||null});if(error){notifyError('Enregistrement de la note',error);return;}closeModal();await loadLiveData();showPage('grades');}
function attendancePage(){const rows=db.attendance.map(a=>`<tr><td>${esc(a.student)}</td><td>${a.date?new Date(a.date+'T00:00:00').toLocaleDateString('fr-FR'):''}</td><td>${esc(a.state)}</td><td>${esc(a.reason||'—')}</td></tr>`).join('');return pageShell('Présences et absences','Suivi quotidien des élèves','Enregistrer une présence','openAttendanceForm()',`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Élève</th><th>Date</th><th>Statut</th><th>Motif</th></tr></thead><tbody>${rows||'<tr><td colspan="4" class="empty">Aucune présence saisie.</td></tr>'}</tbody></table></div></div>`);}
