function studentDirectoryRows(){
 return db.students.map((s,i)=>{const schedules=liveStudentSchedules.filter(x=>String(x.eleve_id)===String(s.id));const due=schedules.reduce((a,x)=>a+Number(x.montant_net||0),0),paid=schedules.reduce((a,x)=>a+Number(x.montant_paye||0),0),rest=schedules.reduce((a,x)=>a+Number(x.reste_a_payer||0),0);const link=liveStudentParentLinks.find(p=>String(p.eleve_id)===String(s.id)),parent=link?.parents;return `<tr data-class="${s.classId||''}" data-sex="${s.sex||''}" data-search="${esc([s.name,s.educmasterId,s.matricule,s.class,s.phone,parent?.phone].join(' ').toLowerCase())}"><td>${i+1}</td><td>${esc(s.educmasterId||'—')}</td><td>${s.photo_url?`<img src="${esc(s.photo_url)}" alt="Photo" style="width:38px;height:44px;object-fit:cover;border-radius:4px">`:'—'}</td><td><b>${esc(s.name)}</b><small style="display:block;color:#64748b">${esc(s.class||'Sans classe')}</small></td><td>${s.birthDate?new Date(s.birthDate+'T00:00:00').toLocaleDateString('fr-FR'):'—'}</td><td>${due.toLocaleString('fr-FR')} FCFA</td><td>${paid.toLocaleString('fr-FR')} FCFA</td><td><b>${rest.toLocaleString('fr-FR')} FCFA</b></td><td>${esc(parent?.telephone||'—')}</td><td>—</td><td class="actions"><button class="btn light" onclick="openEdit('student',${Number(s.id)})">Modifier</button><button class="btn light" onclick="printStudentCard(${Number(s.id)})">Carte</button></td></tr>`}).join('')||'<tr><td colspan="11" class="empty">Aucun apprenant enregistré dans cet établissement.</td></tr>';
}
function filterStudentDirectory(){const cls=val('studentClassFilter'),q=val('studentDirectorySearch').toLowerCase();let visible=0,g=0,b=0;document.querySelectorAll('#studentDirectoryBody tr[data-class]').forEach(r=>{const ok=(!cls||r.dataset.class===cls)&&(!q||r.dataset.search.includes(q));r.style.display=ok?'':'none';if(ok){visible++;if(r.dataset.sex==='F')g++;if(r.dataset.sex==='M')b++;}});const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};set('studentDirectoryCount',visible+' apprenant(s) affiché(s)');set('studentGirls',g);set('studentBoys',b);set('studentTotal',visible);}
