 if(!groupPayStudentOptions.length)return alert("Aucun élève n'est disponible dans l'établissement sélectionné.");
 const classOptions=db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("");
 document.getElementById("modalTitle").textContent="Encaissement de plusieurs tranches";
 document.getElementById("modalBody").innerHTML=`<div class="form-grid">
 <label class="full">Classe (facultatif — pour filtrer les élèves)<select id="groupPayClass" onchange="renderGroupPayStudentOptions()"><option value="">Toutes les classes</option>${classOptions}</select></label>
 <label class="full">Rechercher un élève — les résultats apparaissent à chaque lettre<input id="groupPaySearch" type="search" placeholder="Saisir le nom, prénom ou matricule…" autocomplete="off" oninput="renderGroupPayStudentOptions()"></label>
 <label class="full">Choisir l'élève dans les résultats<select id="groupPayStudent" required><option value="">Commencez la recherche ou choisissez une classe</option></select></label>
 <label>Montant versé (FCFA)<input id="groupPayAmount" type="number" min="1" step="1" required></label>
 <label>Mode de paiement<select id="groupPayMode"><option>Espèces</option><option>Mobile Money</option><option>Virement</option><option>Chèque</option><option>Autre</option></select></label>
 <label>Référence externe<input id="groupPayExternal"></label>
 <label class="full">Observation<textarea id="groupPayObservation" rows="2"></textarea></label>
 </div><p class="muted">La recherche affiche les élèves au fur et à mesure de la saisie. Vous pouvez rechercher dans toutes les classes ou choisir une classe pour filtrer la liste et enchaîner les paiements des élèves de cette classe. Chaque validation crée un reçu individuel récapitulatif. Le montant est réparti automatiquement sur les échéances impayées ; le surplus devient un crédit élève.</p><button class="btn primary" onclick="submitGroupPayment()">Valider et répartir le paiement</button>`;
 renderGroupPayStudentOptions();
 document.getElementById("modal").classList.remove("hidden");
