async function submitGroupPayment(){
 const studentId=Number(val("groupPayStudent")),amount=Number(val("groupPayAmount")),mode=val("groupPayMode"),external=val("groupPayExternal"),observation=val("groupPayObservation");
 if(!studentId||!Number.isFinite(amount)||amount<=0)return alert("Sélectionnez un élève et saisissez un montant positif.");
 const {data,error}=await supabaseClient.rpc("enregistrer_versement_eleve",{p_eleve_id:studentId,p_montant:amount,p_mode:mode,p_reference_externe:external||null,p_observation:observation||null});
 if(error){notifyError("Versement refusé",error);return;}
 const versement=Array.isArray(data)?data[0]:data;
 closeModal();await loadLiveData();showPage("payments");
 if(versement){
   alert(`Versement enregistré. Reçu unique : ${versement.reference_recu}. Crédit utilisé : ${Number(versement.credit_utilise||0).toLocaleString("fr-FR")} FCFA. Surplus crédité : ${Number(versement.surplus_credite||0).toLocaleString("fr-FR")} FCFA. Crédit disponible : ${Number(versement.credit_disponible||0).toLocaleString("fr-FR")} FCFA.`);
   printVersementReceipt(versement,studentId,mode);
 }
}
async function printStoredVersementReceipt(id){
 const v=liveVersements.find(x=>Number(x.id)===Number(id));if(!v)return alert("Reçu groupé introuvable.");
 const affects=(v.versements_affectations||[]).map(a=>({tranche:a.encaissements?.echeance_eleve_id,montant:a.encaissements?.montant,source:a.source==="credit"?"Crédit antérieur":"Versement du jour"}));
 printVersementReceipt({reference_recu:v.reference_recu,montant_recu:v.montant_recu,credit_utilise:v.credit_utilise,surplus_credite:v.surplus_credite,credit_disponible:v.credit_disponible_apres??0,affectations:affects,created_at:v.created_at,annule:!!v.annule||((v.versements_affectations||[]).length>0&&(v.versements_affectations||[]).every(a=>a.encaissements?.annule===true))},v.eleve_id,v.mode_paiement);
}
function printVersementReceipt(v,studentId,mode){
 const st=db.students.find(x=>String(x.id)===String(studentId));const site=currentSite();
 const schedules=liveStudentSchedules.filter(x=>String(x.eleve_id)===String(studentId)&&Number(x.reste_a_payer)>0).sort((a,b)=>{const da=a.date_echeance||null,db=b.date_echeance||null;if(!da&&!db)return Number(a.numero_tranche)-Number(b.numero_tranche);if(!da)return -1;if(!db)return 1;return String(da).localeCompare(String(db))||Number(a.numero_tranche)-Number(b.numero_tranche);});
 const allocations=(v.affectations||[]).map(a=>{const e=liveStudentSchedules.find(x=>Number(x.id)===Number(a.tranche));return `<tr><td>${esc(e?.libelle||("Échéance "+a.tranche))}</td><td>${esc(a.source||"")}</td><td style="text-align:right">${Number(a.montant||0).toLocaleString("fr-FR")} FCFA</td></tr>`}).join("");
 const nextDue=schedules[0]||null;const nextAfter=nextDue?schedules.find(x=>Number(x.numero_tranche)===Number(nextDue.numero_tranche)+1):null;
 const money=n=>Number(n||0).toLocaleString("fr-FR");
 let warning="Scolarité entièrement réglée.";
 if(nextDue){
  const due=nextDue.date_echeance?new Date(nextDue.date_echeance+"T00:00:00"):null;
  const cut5=due?new Date(due.getFullYear(),due.getMonth()+1,5):null;
  const cut6=due?new Date(due.getFullYear(),due.getMonth()+1,6):null;
  const cut11=due?new Date(due.getFullYear(),due.getMonth()+1,11):null;
  const today=new Date();today.setHours(0,0,0,0);
  const dateLabel=due?due.toLocaleDateString("fr-FR"):"À l’inscription (sans date fixe)";
  if(cut11&&today>=cut11){
   const required=Number(nextDue.reste_a_payer||0)+Number(nextAfter?.reste_a_payer||0);
   warning=`À partir du 11 : régler les deux tranches exigibles. ${esc(nextDue.libelle||"Tranche "+nextDue.numero_tranche)} : ${money(nextDue.reste_a_payer)} FCFA${nextAfter?` ; ${esc(nextAfter.libelle||"Tranche "+nextAfter.numero_tranche)} : ${money(nextAfter.reste_a_payer)} FCFA`:""}. Total à régler : ${money(required)} FCFA.`;
  }else if(cut6&&today>=cut6){
   warning=`Retard signalé : ${esc(nextDue.libelle||"Tranche "+nextDue.numero_tranche)} reste à régler (${money(nextDue.reste_a_payer)} FCFA).`;
  }else{
   warning=`Prochaine échéance : ${dateLabel} — ${esc(nextDue.libelle||"Tranche "+nextDue.numero_tranche)}. Montant restant : ${money(nextDue.reste_a_payer)} FCFA.`;
  }
  if(Number(nextDue.montant_paye||0)>0)warning+=` Déjà versé sur cette tranche : ${money(nextDue.montant_paye)} FCFA.`;
 }
 const w=window.open("","_blank");if(!w)return alert("Autorisez les fenêtres contextuelles pour imprimer le reçu.");
 w.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Reçu ${esc(v.reference_recu)}</title><style>@page{size:A4;margin:18mm}body{font-family:Arial;color:#172338}.receipt{max-width:760px;margin:auto;border:2px solid #174a8b;padding:24px}.center{text-align:center;border-bottom:2px solid #174a8b;padding-bottom:12px}table{width:100%;border-collapse:collapse;margin-top:18px}td,th{padding:9px;border:1px solid #d5dbe5;text-align:left}.total{font-size:22px;font-weight:bold}.sign{display:flex;justify-content:space-between;margin-top:55px}@media print{button{display:none}}</style></head><body><div class="receipt"><div class="center"><h1>GROUPE SCOLAIRE LA RÉFÉRENCE</h1><div>${esc(site?.nom||"")} · ${esc(site?.adresse||"")}</div><h2>REÇU DE VERSEMENT</h2>${v.annule?`<h2 style="color:#b42318">ANNULÉ — NE PAS ENCAISSER</h2>`:""}</div><p style="text-align:right"><b>N° ${esc(v.reference_recu)}</b></p><p><b>Élève :</b> ${esc(st?.name||"")} &nbsp; <b>Matricule :</b> ${esc(st?.matricule||"")}<br><b>Classe :</b> ${esc(st?.class||"")}<br><b>Date :</b> ${new Date(v.created_at||Date.now()).toLocaleString("fr-FR")} &nbsp; <b>Mode :</b> ${esc(mode||"")}</p><table><thead><tr><th>Tranche / échéance</th><th>Origine</th><th>Montant affecté</th></tr></thead><tbody>${allocations||'<tr><td colspan="3">Aucune échéance affectée</td></tr>'}</tbody></table><p>Montant reçu : <b class="total">${money(v.montant_recu)} FCFA</b></p><p>Crédit antérieur utilisé : ${money(v.credit_utilise)} FCFA<br>Surplus placé en crédit : ${money(v.surplus_credite)} FCFA<br><b>Crédit disponible après opération : ${money(v.credit_disponible)} FCFA</b></p><p><b>Situation après versement :</b> ${warning}</p><div class="sign"><span>Cachet et signature</span><span>La comptabilité</span></div><p style="text-align:center">Merci pour votre confiance.</p><button onclick="window.print()">Imprimer le reçu A4</button></div></body></html>`);w.document.close();setTimeout(()=>w.print(),400);
}
