async function login(){
 const identity=val("loginUser").trim(),password=val("loginPass");
 if(!supabaseClient){alert("Connexion impossible : le service Supabase ne s'est pas chargé.");return}
 if(!(/^AG[0-9]{6}$/i.test(identity)||/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(identity))||!password){alert("Saisissez votre numéro AG ou votre adresse e-mail et votre mot de passe.");return}
 const btn=document.querySelector(".login-card button");btn.disabled=true;btn.textContent="Connexion...";
 try{
  const email=/^AG[0-9]{6}$/i.test(identity)?identity.toLowerCase()+"@login.aglareference.invalid":identity.toLowerCase();
  const {error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;
  liveMode=true;await loadLiveData();if(!currentProfile?.actif)throw new Error("Ce compte est désactivé. Contactez l'administration.");
  const selectedRole=val("loginRole");
  const roleAliases={direction:["direction","directeur"],administrateur_general:["administrateur_general"],censeur:["censeur"],enseignant:["enseignant","professeur"],comptable:["comptable","caissier"],surveillant:["surveillant"],secretariat:["secretariat","secretaire"],parent:["parent"]};
  if(!(roleAliases[selectedRole]||[]).includes(currentProfile.role)){
    await supabaseClient.auth.signOut();
    currentProfile=null;liveMode=false;
    throw new Error("Ce compte n'est pas autorisé à ouvrir l'espace sélectionné. Choisissez votre fonction réelle ou contactez l'administrateur.");
  }
  document.getElementById("login").classList.add("hidden");document.getElementById("app").classList.remove("hidden");
  const userLabel=document.querySelector(".topbar .user");if(userLabel)userLabel.textContent="👤 "+[currentProfile.prenom,currentProfile.nom].filter(Boolean).join(" ");
  showPage("dashboard");
 }catch(e){notifyError("Connexion",e);await supabaseClient.auth.signOut()}
 finally{btn.disabled=false;btn.textContent="Se connecter"}
}
