function tariffCodeForStudent(st){
 const cls=db.classes.find(x=>String(x.id)===String(st?.classId));const c=String((st?.class||"")+" "+(cls?.series||"")).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
 if(c.includes("matern"))return "MATERNELLE";if(/\bci\b|\bcp\b/.test(c))return "CI-CP";if(c.includes("ce1")||c.includes("ce2"))return "CE1-CE2";if(c.includes("cm1")||c.includes("cm2"))return "CM1-CM2";
 if(c.includes("6e"))return "6EME";if(c.includes("5e"))return "5EME";if(c.includes("4e"))return "4EME";if(c.includes("3e"))return "3EME";
 if(c.includes("2nde")||c.includes("seconde"))return c.includes("g1")||c.includes("g2")||c.includes("g3")?"2NDE-G1-G3":"2NDE-ABCD";
 if(c.includes("1ere")||c.includes("premiere"))return c.includes("c")?"1ERE-C-G1-G3":"1ERE-ABD-G2";
 if(c.includes("tle")||c.includes("terminal"))return c.includes("c")||c.includes("g1")||c.includes("g3")?"TLE-C-G1-G3":"TLE-ABD-G2";return null;
}
function applyStudentTariff(){
 const studentId=val("f_student"),trancheLabel=val("f_tranche");const st=db.students.find(x=>String(x.id)===String(studentId));const code=tariffCodeForStudent(st);const tariff=liveTariffs.find(x=>x.code_niveau===code);const due=document.getElementById("f_due");if(!due||!tariff)return;
 const n=parseInt(String(trancheLabel).match(/[1-7]/)?.[0]||"1",10);const e=(tariff.echeances_tarifaires||[]).find(x=>Number(x.numero_tranche)===n);if(e)due.value=Number(e.montant);
}
